#!/usr/bin/env bash
# Downloads the Material Symbols variable fonts (Outlined, Rounded, Sharp; axes FILL, wght, GRAD, opsz) and their
# codepoint lists from google/material-design-icons (Apache-2.0) into tools/icons/.cache/fonts (gitignored).
# Only path data derived from these fonts is committed (app/.../view/Symbols.kt, generated by gen_symbols.py).
set -euo pipefail
out="$(cd "$(dirname "$0")" && pwd)/.cache/fonts"
mkdir -p "$out"
base=https://raw.githubusercontent.com/google/material-design-icons/master
for s in Outlined Rounded Sharp; do
  f="MaterialSymbols$s%5BFILL,GRAD,opsz,wght%5D"
  [[ -s "$out/MaterialSymbols$s.ttf" ]] || curl -fsSL -o "$out/MaterialSymbols$s.ttf" "$base/variablefont/$f.ttf"
  [[ -s "$out/MaterialSymbols$s.codepoints" ]] || curl -fsSL -o "$out/MaterialSymbols$s.codepoints" "$base/variablefont/$f.codepoints"
done
[[ -s "$out/LICENSE" ]] || curl -fsSL -o "$out/LICENSE" "$base/LICENSE"
ls -la "$out"
